import{_ as t,c as s,o as n,j as e,a as l}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"周易辑闻","description":"周易辑闻 - 周易辑闻","frontmatter":{"title":"周易辑闻","description":"周易辑闻 - 周易辑闻"},"headers":[],"relativePath":"zh/classics/jiwen/001.md","filePath":"zh/classics/jiwen/001.md"}'),r={name:"zh/classics/jiwen/001.md"};function i(c,a,o,p,d,m){return n(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"周易辑闻",tabindex:"-1"},[l("周易辑闻 "),e("a",{class:"header-anchor",href:"#周易辑闻","aria-label":"Permalink to “周易辑闻”"},"​")],-1),e("p",null,"广大无不备，夫惟易道然。辑闻传汴水，述学衍先天。观彼多合圣，切子斯体乾。影钞犹识宋，远矣缅韦编。钦定四库全书经部一周易辑闻易类提要：",-1),e("p",null,"臣 等谨案：周易辑闻六卷、附易雅一卷、筮宗一卷，宋赵汝梅撰。汝梅，商王元份之七世孙，资政殿大学士善湘之子，理宗时官至户部侍郎。考宋史赵善湘傅载其说易之书，有约说八卷、或问四卷、指要四卷、续问八卷、补过六卷。盖研究是经，用功最久，故汝梅承其家",-1),e("p",null,"学，以作是编。其说据汉书儒林传称费直惟以彖、象、繋辞十篇文言解说上下经，疑说卦、序卦、杂卦皆为汉儒窜入。又以繋辞多称「子曰」，定为门人所记，非夫子之书，因置此诸傅，惟注经文。其以彖傅散附彖辞，小象散附爻辞，仍用王弼之本。其以大象移于卦画之后，彖辞之前，以文言散附乾坤彖傅及小象后，则又汝梅之新意。割裂颠倒，殊属师心。又王弼本虽移傅附经，尚有「彖曰」、「象曰」、「文言曰」字，以存识别，汝梅并此而去之，致使经传混淆，范然莫辨，尤为治丝而棼。其每卦之首，皆以卦变立论，亦未免偏主一隅。然其说推阐详明，于比应乘承之理，盈虚消长之机，皆有所发挥，不同穿凿。于宋人易说之中，犹为明白笃实。易雅一卷，总释名义，略如尔雅之释诗，故名曰「雅」。其目：曰通释，曰书释，曰学释，曰情释，曰位释，曰象释，曰辞释，曰变释，曰占释，曰卦变释，曰爻变释，曰得失释，曰八卦释，曰六爻释，曰阴阳释，曰太极名义释，曰象数体用释，曰图书释，凡十八篇。其论图书曰：「易有衍数，有积数。自五衍而为五十者，衍数也；自一、二、三、四、五积而为五十五者，积数也。图书二数皆积数之俦，不可以与于揲蓍也。故舍图书之名而论二数，则自有妙理；强二数以图、书之名，则于经无据。」可谓喜于解纷矣。筮宗一卷，朱彝尊经义考作三卷，盖是书原本题明本第一，述筮第二先傅考第三，彝尊以一篇为一卷也。其推明大衍之数，颇为明白，于诸家旧说，一一条辨，亦具有考证云。乾隆四十四年九月恭校上。",-1),e("p",null,"总纂官 臣 纪昀、 臣 陆锡熊、 臣 孙士毅，总校官 臣 陆费墀。周易辑闻原序：",-1),e("p",null,"易道函三极而神万化，易书立三极而万化神。道主于有，书主于用也。体易君子处而用身，出而用世，皆于此焉出以用为动，则静者其体也。动之变无穷，近而显者，百姓与能；远而微者，贤智未易知。夫道妙于无形，而著于有象，确乎不易，而变动不居。以虚而言，则至于无畔；以固而言，则或有所不通。圣人于是立象倚数，探赜索隐，载之于书，莫非日用常行之实。使人因有象而悟无形之妙，即变易以求不易之方，玩而体之，服而行之，言有据而动有则，措诸事业，自诚意正心以至于齐家治国平天下，随用辄效。此体用兼该之学，伏羲画卦之旨，文、周忧世之情，夫子传易之志也。汝梅齿耄学荒，何敢言易？独念先君子自始至夫，于易凡六稿，日进日益，末稿题曰「补过」，汝梅得于口授者居多。外除以来逾二十载，因辑所闻于篇，庶不忘先君子之教，且以观吾过云。汴水赵汝梅序。",-1)])])}const f=t(r,[["render",i]]);export{_ as __pageData,f as default};
